// src/tools/helpers.ts
function toolResult(data) {
  return {
    content: [
      {
        type: "text",
        text: JSON.stringify(data, null, 2)
      }
    ]
  };
}
function toolError(error2) {
  const message = error2 instanceof Error ? error2.message : String(error2);
  return {
    content: [
      {
        type: "text",
        text: `Error: ${message}`
      }
    ],
    isError: true
  };
}

