// src/resources/index.ts
function registerAllResources(server, client) {
  server.resource(
    "panel-stats",
    "remnawave://stats",
    {
      description: "Current Remnawave panel statistics (users, nodes, traffic, system)",
      mimeType: "application/json"
    },
    async () => {
      const stats = await client.getStats();
      return {
        contents: [
          {
            uri: "remnawave://stats",
            mimeType: "application/json",
            text: JSON.stringify(stats, null, 2)
          }
        ]
      };
    }
  );
  server.resource(
    "panel-nodes",
    "remnawave://nodes",
    {
      description: "Status of all Remnawave nodes (online/offline, traffic)",
      mimeType: "application/json"
    },
    async () => {
      const nodes = await client.getNodes();
      return {
        contents: [
          {
            uri: "remnawave://nodes",
            mimeType: "application/json",
            text: JSON.stringify(nodes, null, 2)
          }
        ]
      };
    }
  );
  server.resource(
    "panel-health",
    "remnawave://health",
    {
      description: "Remnawave panel health check",
      mimeType: "application/json"
    },
    async () => {
      const health = await client.getHealth();
      return {
        contents: [
          {
            uri: "remnawave://health",
            mimeType: "application/json",
            text: JSON.stringify(health, null, 2)
          }
        ]
      };
    }
  );
  server.resource(
    "user-details",
    new ResourceTemplate("remnawave://users/{userId}", {
      list: void 0
    }),
    {
      description: "Detailed information about a specific Remnawave user",
      mimeType: "application/json"
    },
    async (uri, params) => {
      const userId = params.userId;
      const user = await client.getUserById(userId);
      return {
        contents: [
          {
            uri: uri.href,
            mimeType: "application/json",
            text: JSON.stringify(user, null, 2)
          }
        ]
      };
    }
  );
}

// src/prompts/index.ts
function registerAllPrompts(server) {
  server.prompt(
    "create_user_wizard",
    "Step-by-step guide to create a new VPN user",
    {
      username: external_exports.string().describe("Username for the new user")
    },
    async ({ username }) => ({
      messages: [
        {
          role: "user",
          content: {
            type: "text",
            text: `I want to create a new VPN user with username "${username}". Please guide me through the process:

1. First, check if the username is already taken using users_get_by_username
2. Get the list of available config profiles using config_profiles_list
3. Get the list of available internal squads using squads_list
4. Create the user with appropriate settings (ask me about traffic limit, expiration date, and which squads to assign)
5. Confirm the user was created successfully and show the subscription URL`
          }
        }
      ]
    })
  );
  server.prompt(
    "node_diagnostics",
    "Diagnose issues with a specific node",
    {
      nodeUuid: external_exports.string().describe("UUID of the node to diagnose")
    },
    async ({ nodeUuid }) => ({
      messages: [
        {
          role: "user",
          content: {
            type: "text",
            text: `Please run diagnostics on node ${nodeUuid}:

1. Get node details using nodes_get
2. Check system health using system_health
3. Get node metrics using system_nodes_metrics
4. Check bandwidth stats using system_bandwidth_stats
5. Summarize the node's status: connection state, xray version, uptime, traffic usage, online users
6. Flag any issues found (offline, high traffic usage, errors)`
          }
        }
      ]
    })
  );
  server.prompt(
    "traffic_report",
    "Generate a traffic usage report",
    {
      startDate: external_exports.string().optional().describe("Start date (ISO 8601)"),
      endDate: external_exports.string().optional().describe("End date (ISO 8601)")
    },
    async ({ startDate, endDate }) => {
      const period = startDate && endDate ? `from ${startDate} to ${endDate}` : "current";
      return {
        messages: [
          {
            role: "user",
            content: {
              type: "text",
              text: `Generate a traffic report for the ${period} period:

1. Get overall system stats using system_stats
2. Get bandwidth statistics using system_bandwidth_stats
3. Get node statistics using system_nodes_statistics
4. List all users and their traffic using users_list
5. Provide a summary including:
   - Total traffic consumed
   - Per-node traffic breakdown
   - Top users by traffic consumption
   - Users who exceeded their traffic limits
   - Users with expired subscriptions`
            }
          }
        ]
      };
    }
  );
  server.prompt(
    "user_audit",
    "Complete audit of a specific user",
    {
      userId: external_exports.number().describe("User numeric ID to audit")
    },
    async ({ userId }) => ({
      messages: [
        {
          role: "user",
          content: {
            type: "text",
            text: `Perform a complete audit of user ${userId}:

1. Get full user details using users_get
2. Get subscription info using subscriptions_get_by_user_id
3. Get HWID devices using hwid_devices_list
4. Summarize:
   - Account status and expiration
   - Traffic usage vs limit
   - Subscription URL and last access
   - Connected devices (HWID)
   - Squad memberships
   - Any issues or concerns`
          }
        }
      ]
    })
  );
  server.prompt(
    "edit_config_profile",
    "Step-by-step guide to edit a config profile core config",
    {
      uuid: external_exports.string().describe("UUID of the config profile to edit")
    },
    async ({ uuid: uuid2 }) => ({
      messages: [
        {
          role: "user",
          content: {
            type: "text",
            text: `I want to edit the Xray/sing-box core config of config profile ${uuid2}. Follow this workflow:

1. Fetch the current profile with config_profiles_get (uuid). The response includes the full \`config\` object.
2. Optionally fetch config_profiles_get_computed_config if I need the resolved/snippet-expanded view.
3. Apply my requested changes to that \`config\` object (inbounds, outbounds, routing, dns, etc.).
4. Call config_profiles_update with the same uuid and the **full** modified \`config\` object. The API replaces the entire core config; do not send a partial patch. You may also pass \`name\` to rename the profile.
5. Show me what changed and confirm the update succeeded.

config_profiles_update accepts uuid (required), optional name, and optional config (the full core configuration object).`
          }
        }
      ]
    })
  );
  server.prompt(
    "bulk_user_cleanup",
    "Find and manage expired or inactive users",
    {},
    async () => ({
      messages: [
        {
          role: "user",
          content: {
            type: "text",
            text: `Help me clean up users:

1. List all users using users_list with a large page size
2. Identify:
   - Users with EXPIRED status
   - Users with DISABLED status
   - Users with LIMITED status (exceeded traffic)
   - Users who haven't connected recently
3. Present the findings in a clear table
4. Ask what action to take (disable, delete, extend, reset traffic)
5. Execute the chosen action after confirmation`
          }
        }
      ]
    })
  );
}

// src/server.ts
function createServer(config2) {
  const server = new McpServer({
    name: "remnawave-mcp",
    version: "1.6.0"
  });
  const client = new RemnawaveClient(config2);
  registerAllTools(server, client, config2.readonly);
  registerAllResources(server, client);
  registerAllPrompts(server);
  return server;
}

// src/index.ts
try {
  const config2 = loadConfig();
  const server = createServer(config2);
  const transport = new StdioServerTransport();
  await server.connect(transport);
} catch (error2) {
  const message = error2 instanceof Error ? error2.message : String(error2);
  console.error(`[remnawave-mcp] ${message}`);
  process.exit(1);
}
